import 'package:flutter/material.dart'; import '../../../../shared/enums/activity_category.dart'; import '../../../home/presentation/widgets/category_chip.dart';
class ActivityCategorySelector extends StatelessWidget{const ActivityCategorySelector({super.key,required this.value,required this.onChanged});final ActivityCategory value;final ValueChanged<ActivityCategory> onChanged;@override Widget build(BuildContext context){final cats=ActivityCategory.values.take(6).toList();return SizedBox(height:98,child:ListView.separated(scrollDirection:Axis.horizontal,itemBuilder:(_,i)=>CategoryChipCard(category:cats[i],selected:value==cats[i],onTap:()=>onChanged(cats[i])),separatorBuilder:(_,__)=>const SizedBox(width:10),itemCount:cats.length));}}
